func TestDuplicatePropertyFails(t *testing.T) {
	pth := filepath.Join(
		ourtesting.TestDataDir,
		"Xml",
		"Expected",
		"childA",
		"minimal.xml",
	)

	bb, err := os.ReadFile(pth)
	if err != nil {
		t.Fatalf("Failed to read the file %s: %s", pth, err.Error())
	}

	text := string(bb)

	// We cut the element of the property out of the recorded example and put it in
	// a second time, just before the closing tag of the instance.
	start := strings.Index(text, "<number>")

	var property string
	if start >= 0 {
		end := strings.Index(
			text[start:], "</number>",
		) + start
		property = text[start : end+9]
	} else {
		// The element is written self-closing in the example, an empty list being
		// the usual reason. We write that very element out ourselves.
		property = "<number/>"
	}

	insertionIndex := strings.LastIndex(
		text, "</childA>",
	)
	if insertionIndex < 0 {
		t.Fatalf(
			"We expect the recorded example to contain the closing tag %s, "+
				"but it does not: %s",
			"</childA>", pth,
		)
	}

	brokenText := text[:insertionIndex] + property + text[insertionIndex:]

	decoder := xml.NewDecoder(strings.NewReader(brokenText))

	_, deseriaErr := ourxmlization.Unmarshal(decoder)
	if deseriaErr == nil {
		t.Fatalf(
			"Expected a de-serialization error when the property %s is given twice, "+
				"but got none",
			"number",
		)
	}
}

// Give the text of the first recorded example of IChildA with
// the content of the element `xmlName` replaced by `text`.
func patchChildAWith(
	t *testing.T,
	xmlName string,
	text string,
) string {
	pths := ourtesting.FindFilesBySuffixRecursively(
		filepath.Join(
			ourtesting.TestDataDir,
			"Xml",
			"Expected",
			"childA",
		),
		".xml",
	)
	sort.Strings(pths)

	if len(pths) == 0 {
		t.Fatalf(
			"Expected at least one recorded example of %s, but got none",
			"childA",
		)
	}

	bb, err := os.ReadFile(pths[0])
	if err != nil {
		t.Fatalf("Failed to read the file %s: %s", pths[0], err.Error())
	}

	original := string(bb)

	start := strings.Index(original, "<"+xmlName+">") + len(xmlName) + 2
	end := strings.Index(original, "</"+xmlName+">")

	return original[:start] + text + original[end:]
}

// Read the first recorded example of IChildA with the content of
// the element `xmlName` replaced by `text`.
func readChildAWith(
	t *testing.T,
	xmlName string,
	text string,
) ourtypes.IChildA {
	patched := patchChildAWith(t, xmlName, text)

	decoder := xml.NewDecoder(strings.NewReader(patched))
	deserialized, deseriaErr := ourxmlization.Unmarshal(decoder)
	if deseriaErr != nil {
		t.Fatalf(
			"Expected no de-serialization error on %v, but got: %s",
			patched, deseriaErr.Error(),
		)
	}

	instance, ok := deserialized.(ourtypes.IChildA)
	if !ok {
		t.Fatalf("Expected an instance of IChildA, but got %T", deserialized)
	}

	return instance
}

func TestNumberReadFrom9007199254740991(t *testing.T) {
	instance := readChildAWith(
		t,
		"number",
		"9007199254740991",
	)

	got := instance.Number()
	expected := int64(9007199254740991)
	if got != expected {
		t.Fatalf("Expected %v, but got %v", expected, got)
	}
}

func TestNumberReadFromMinus9007199254740991(t *testing.T) {
	instance := readChildAWith(
		t,
		"number",
		"-9007199254740991",
	)

	got := instance.Number()
	expected := int64(-9007199254740991)
	if got != expected {
		t.Fatalf("Expected %v, but got %v", expected, got)
	}
}

func TestNumberReadFrom9007199254740992Fails(t *testing.T) {
	patched := patchChildAWith(
		t,
		"number",
		"9007199254740992",
	)

	decoder := xml.NewDecoder(strings.NewReader(patched))
	_, err := ourxmlization.Unmarshal(decoder)

	expected := "Expected an integer, but got 9007199254740992, which is outside the safe integer range [-2^53 + 1, 2^53 - 1]"
	deseriaErr, ok := err.(*ourxmlization.DeserializationError)
	if !ok || deseriaErr.Message != expected {
		t.Fatalf("Expected the de-serialization error %q, but got: %v", expected, err)
	}
}

